6	)
7	
8	// The worked example from the idle-partition spec: with window 1000,
9	// partition 0 at watermark 2000 and partition 1 only holding two events at
10	// time 800 (sum 5), declaring partition 1 idle immediately closes k's
11	// [0,1000) window. Resuming partition 1 at 1999 must fail; resuming at 2000
12	// succeeds and the closed window is not emitted again.
13	func TestAggregateIdleSpecExample(t *testing.T) {
14		input := strings.Join([]string{
15			`{"type":"watermark","time":2000,"partition":0}`,
16			`{"type":"event","key":"k","time":800,"value":2,"partition":1}`,
17			`{"type":"event","key":"k","time":800,"value":3,"partition":1}`,
18			`{"type":"idle","partition":1}`, // line 4: closes [0,1000) at once
19		}, "\n")
20		stdout, stderr, err := runPartitioned(t, input, 1000, 2)
21		if err != nil {
22			t.Fatalf("unexpected error: %v", err)
23		}
24		if stderr != "" {
25			t.Fatalf("unexpected stderr: %q", stderr)
26		}
27		want := `{"key":"k","start":0,"end":1000,"count":2,"sum":5}` + "\n"
28		if stdout != want {
29			t.Fatalf("stdout mismatch:\n got: %q\nwant: %q", stdout, want)
30		}
31	
32		// Resume below the current effective watermark (2000) fails, and the
33		// already produced output survives.
34		failInput := input + "\n" + `{"type":"watermark","time":1999,"partition":1}` + "\n"
35		got, _, err := runPartitioned(t, failInput, 1000, 2)
36		if err == nil {
37			t.Fatal("expected resume at 1999 to fail")
38		}
39		inputErr, ok := err.(*InputError)
40		if !ok {
41			t.Fatalf("expected *InputError, got %T: %v", err, err)
42		}
43		if inputErr.Line != 5 {
44			t.Errorf("line = %d, want 5", inputErr.Line)
45		}
46		if !strings.Contains(inputErr.Reason, "partition 1") || !strings.Contains(inputErr.Reason, "2000") {
47			t.Errorf("reason = %q, want it to name partition 1 and boundary 2000", inputErr.Reason)
48		}
49		if got != want {
50			t.Fatalf("prior output must be retained on failed resume, got %q", got)
51		}
52	
53		// Resume exactly at the boundary succeeds and emits nothing new.
54		okInput := input + "\n" + `{"type":"watermark","time":2000,"partition":1}` + "\n"
55		got, _, err = runPartitioned(t, okInput, 1000, 2)
56		if err != nil {
57			t.Fatalf("resume at 2000 must succeed, got %v", err)
58		}
59		if got != want {
60			t.Fatalf("resume must not re-emit the closed window, got %q", got)
61		}
62	}
63	
64	// An idle declaration does nothing for closure while another non-idle
65	// partition has never reported a watermark.
66	func TestAggregateIdleWaitsForOtherReporters(t *testing.T) {
67		input := strings.Join([]string{
68			`{"type":"event","key":"k","time":100,"value":1,"partition":0}`,
69			`{"type":"watermark","time":5000,"partition":0}`,
70			`{"type":"idle","partition":1}`, // partition 2 (of 3) never reported either
71		}, "\n")
72		stdout, _, err := runPartitioned(t, input, 1000, 3)
73		if err != nil {
74			t.Fatalf("unexpected error: %v", err)
75		}
76		if stdout != "" {
77			t.Fatalf("no effective watermark while a non-idle partition is silent, got %q", stdout)
78		}
79	}
80	
81	// Every non-idle partition having reported: the idle record itself advances
82	// the effective watermark to the min of the rest and closes windows.
83	func TestAggregateIdleClosesImmediately(t *testing.T) {
84		input := strings.Join([]string{
85			`{"type":"event","key":"k","time":100,"value":1,"partition":0}`,
86			`{"type":"watermark","time":5000,"partition":0}`,
87			`{"type":"watermark","time":2000,"partition":1}`, // min would be 2000, p2 unreported
88			`{"type":"idle","partition":2}`,                  // exclude p2: min = 2000, closes [0,1000)
89		}, "\n")
90		stdout, _, err := runPartitioned(t, input, 1000, 3)
91		if err != nil {
92			t.Fatalf("unexpected error: %v", err)
93		}
94		want := `{"key":"k","start":0,"end":1000,"count":1,"sum":1}` + "\n"
95		if stdout != want {
96			t.Fatalf("stdout = %q, want %q", stdout, want)
97		}
98	}
99	
100	// A partition that has never reported a watermark may be declared idle
101	// before any effective watermark exists.
102	func TestAggregateIdleBeforeAnyWatermark(t *testing.T) {
103		input := strings.Join([]string{
104			`{"type":"idle","partition":1}`,
105			`{"type":"event","key":"k","time":100,"value":4,"partition":0}`,
106			`{"type":"watermark","time":1000,"partition":0}`, // only p0 active: effective = 1000
107		}, "\n")
108		stdout, _, err := runPartitioned(t, input, 1000, 2)
109		if err != nil {
110			t.Fatalf("unexpected error: %v", err)
111		}
112		want := `{"key":"k","start":0,"end":1000,"count":1,"sum":4}` + "\n"
113		if stdout != want {
114			t.Fatalf("stdout = %q, want %q", stdout, want)
115		}
116	}
117	
118	// Repeated idle declarations succeed and never produce duplicate output.
119	func TestAggregateIdleRepeatedIsNoop(t *testing.T) {
120		input := strings.Join([]string{
121			`{"type":"event","key":"k","time":100,"value":1,"partition":0}`,
122			`{"type":"watermark","time":1000,"partition":0}`,
123			`{"type":"idle","partition":1}`, // closes [0,1000)
124			`{"type":"idle","partition":1}`,
125			`{"type":"idle","partition":1}`,
126		}, "\n")
127		stdout, _, err := runPartitioned(t, input, 1000, 2)
128		if err != nil {
129			t.Fatalf("unexpected error: %v", err)
130		}
131		want := `{"key":"k","start":0,"end":1000,"count":1,"sum":1}` + "\n"
132		if stdout != want {
133			t.Fatalf("stdout = %q, want %q", stdout, want)
134		}
135	}
136	
137	// When all partitions go idle after an effective watermark existed, the last
138	// effective watermark is retained; after a partition resumes at the boundary,
139	// events below the retained watermark are still judged late.
140	func TestAggregateAllIdleRetainsWatermark(t *testing.T) {
141		input := strings.Join([]string{
142			`{"type":"event","key":"k","time":100,"value":1,"partition":0}`,
143			`{"type":"watermark","time":1000,"partition":0}`,
144			`{"type":"watermark","time":1000,"partition":1}`,                // effective = 1000, closes [0,1000)
145			`{"type":"idle","partition":0}`,                                 // only p1 active, effective stays 1000
146			`{"type":"idle","partition":1}`,                                 // all idle: retained 1000, not infinite
147			`{"type":"watermark","time":1000,"partition":0}`,                // resume at boundary; [1000,2000) stays open
148			`{"type":"event","key":"k","time":999,"value":1,"partition":0}`, // late vs retained 1000
149		}, "\n")
150		stdout, stderr, err := runPartitioned(t, input, 1000, 2)
151		if err != nil {
152			t.Fatalf("unexpected error: %v", err)
153		}
154		wantOut := `{"key":"k","start":0,"end":1000,"count":1,"sum":1}` + "\n"
155		if stdout != wantOut {
156			t.Fatalf("stdout = %q, want %q", stdout, wantOut)
157		}
158		wantErr := "line 7: late event time=999 below current watermark 1000, skipped\n"
159		if stderr != wantErr {
160			t.Fatalf("stderr = %q, want %q", stderr, wantErr)
161		}
162	}
163	
164	// All idle before any effective watermark was ever produced: it stays
165	// unknown rather than becoming an infinite watermark. When a partition
166	// resumes alone the effective watermark is its value (the min over the
167	// remaining active set).
168	func TestAggregateAllIdleNeverProducedStaysUnknown(t *testing.T) {
169		// Internal state: every partition idle with no watermark ever reported
170		// yields no effective watermark.
171		s := &aggregateState{
172			windowMillis:  1000,
173			windows:       make(map[windowID]*windowState),
174			partitions:    2,
175			partWatermark: make(map[int64]*int64),
176			idle:          map[int64]bool{0: true, 1: true},
177		}
178		if s.effectiveWatermark() != nil {
179			t.Fatal("effective watermark must stay unknown when all idle and none ever reported")
180		}
181	
182		// Through the public API: resuming one partition sets the effective
183		// watermark to its value; watermark 1000 closes no window.
184		input := strings.Join([]string{
185			`{"type":"idle","partition":0}`,
186			`{"type":"idle","partition":1}`,
187			`{"type":"watermark","time":1000,"partition":0}`, // resume: active set {p0} -> 1000
188		}, "\n")
189		stdout, _, err := runPartitioned(t, input, 1000, 2)
190		if err != nil {
191			t.Fatalf("unexpected error: %v", err)
192		}
193		if stdout != "" {
194			t.Fatalf("watermark 1000 closes no window, got %q", stdout)
195		}
196	}
197	
198	// An event for an idle partition is fatal; it is never accepted as a late
199	// skip and never resumes the partition.
200	func TestAggregateEventWhileIdleFatal(t *testing.T) {
201		input := strings.Join([]string{
202			`{"type":"event","key":"k","time":100,"value":1,"partition":0}`,
203			`{"type":"watermark","time":1000,"partition":0}`,
204			`{"type":"idle","partition":1}`,                                  // closes [0,1000)
205			`{"type":"event","key":"k","time":1500,"value":1,"partition":1}`, // line 4 fatal
206		}, "\n")
207		stdout, stderr, err := runPartitioned(t, input, 1000, 2)
208		if err == nil {
209			t.Fatal("expected error for event on idle partition")
210		}
211		inputErr, ok := err.(*InputError)
212		if !ok {
213			t.Fatalf("expected *InputError, got %T: %v", err, err)
214		}
215		if inputErr.Line != 4 {
216			t.Errorf("line = %d, want 4", inputErr.Line)
217		}
218		if !strings.Contains(inputErr.Reason, "idle partition 1") {
219			t.Errorf("reason = %q, want it to name idle partition 1", inputErr.Reason)
220		}
221		if stderr != "" {
222			t.Fatalf("idle event must be fatal, not a late skip, got stderr %q", stderr)
223		}
224		want := `{"key":"k","start":0,"end":1000,"count":1,"sum":1}` + "\n"
225		if stdout != want {
226			t.Fatalf("earlier output retained, got %q want %q", stdout, want)
227		}
228	}
229	
230	// Resume validation: the resume time must be at least the partition's own
231	// previous watermark and the current effective watermark; equality resumes.
232	func TestAggregateIdleResumeBoundaries(t *testing.T) {
233		cases := []struct {
234			name      string
235			lines     []string
236			resume    string
237			wantError bool
238			wantInMsg string
239		}{
240			{
241				"below own previous",
242				[]string{
243					`{"type":"watermark","time":5000,"partition":0}`,
244					`{"type":"watermark","time":2000,"partition":1}`,
245					`{"type":"idle","partition":1}`, // effective jumps to 5000
246				},
