// idleBatchInput is the shared fixture for the "one idle declaration closes
// several overlapping sliding windows at once" guarantees.
//
// Window length 1000ms, starts every 600ms (0, 600, 1200, ...), two
// partitions. Both partitions have fed overlapping windows; partition 0 is
// far ahead while partition 1 stays at watermark 600. Declaring partition 1
// idle drops it from the effective watermark, which immediately jumps to
// partition 0's 1200 and closes one batch of windows:
//
//   - "a" p0 @100  value 2 -> [0,1000)
//   - "k" p0 @700  value 4 + p1 @900 value 6 -> [0,1000) count2 sum10
//   - "b" p0 @700  value 5 -> [600,1600)
//   - "k" p0 @700  value 4 + p1 @900 value 6 -> [600,1600) count2 sum10
//
// At effective watermark 1200 only windows with end <= 1200 close, so the
// ready batch is:
//
//	[0,1000)  "a" end 1000
//	[0,1000)  "k" end 1000
//	[600,1600) "b" is end 1600 -> stays open
//
// plus a window ending exactly at 1200 so different keys share an end time:
//
//   - "b" p0 @200 value 7 -> [0,1000) and one window ending at 1200. With
//     length 1000 and slide 600 no start k*600 has start+1000 == 1200, so a
//     shared-end 1200 window comes from [200,1200) only via slide 600? No
//     such aligned window exists; instead use the genuinely shared end 1000
//     (keys "a" and "k") and a second shared end via key "b":
//
// The concrete ready set below is: end 1000 keys "a" and "k" (shared end),
// and end 1200 key "b" alone. To produce end 1200 under slide 600 a window
// would need start 200, which is not a multiple of 600; so the second end is
// reached by an event whose [600,1600) window is *not* ready, while key "b"
// also has a [0,1000) window. The batch therefore is exactly:
//
//	{"a", [0,1000)}  {"k", [0,1000)}   (end 1000, keyed UTF-8: "a" < "k")
//	{"b", [200,1200)} is impossible at slide 600; see build below.
//
// To keep the alignment honest, the second end time is 1200 reached with
// window length 1000 over a start of 200 only when slide divides it; the
// fixture instead places "b" so it shares end 1000 as a *third* key and adds
// a distinct end 1600 that must NOT close, proving the watermark boundary.
// See idleBatchLines: the real ready batch (three results, two end times) is
// documented at idleBatchWant.
func idleBatchLines() []string {
	return []string{
		`{"type":"event","key":"a","time":100,"value":2,"partition":0}`,  // [0,1000)
		`{"type":"event","key":"b","time":700,"value":5,"partition":0}`,  // [0,1000),[600,1600)
		`{"type":"event","key":"k","time":700,"value":4,"partition":0}`,  // [0,1000),[600,1600)
		`{"type":"event","key":"k","time":900,"value":6,"partition":1}`,  // [0,1000),[600,1600)
		`{"type":"watermark","time":1200,"partition":0}`,                 // p0 ahead
		`{"type":"watermark","time":600,"partition":1}`,                  // effective = 600: nothing closes
		`{"type":"idle","partition":1}`,                                  // effective = 1200: closes end<=1200
		`{"type":"watermark","time":1600,"partition":0}`,                 // only reached if failure doesn't stop
	}
}

// idleBatchWant is the complete, in-order batch produced by the line-7 idle
// declaration on a healthy writer: first by end ascending (1000 before
// 1600), then by key UTF-8 byte order within end 1000 ("a" < "b" < "k").
// End-1600 windows stay open (1200 < 1600), proving the watermark boundary.
func idleBatchWant() string {
	return strings.Join([]string{
		`{"key":"a","start":0,"end":1000,"count":1,"sum":2}`,
		`{"key":"b","start":0,"end":1000,"count":1,"sum":5}`,
		`{"key":"k","start":0,"end":1000,"count":2,"sum":10}`,
		``,
	}, "\n")
}

// runIdleBatch wires the fixture into the public entry point with arbitrary
// writers; blank blankCount physical blank lines are inserted before the idle
// declaration to verify line numbers are physical, not record counts.
func runIdleBatch(t *testing.T, out, late io.Writer, blankCount int) error {
	t.Helper()
	lines := idleBatchLines()
	if blankCount > 0 {
		head := append([]string{}, lines[:6]...)
		for i := 0; i < blankCount; i++ {
			head = append(head, "")
		}
		lines = append(head, lines[6:]...)
	}
	return RunAggregatePartitionedSliding(strings.NewReader(strings.Join(lines, "\n")+"\n"),
		1000, 600, 2, out, late)
