// closes every window ready under the remaining partition's watermark.
// Pre-idle events from both partitions are retained and merged per key/window,
// ordering is end-ascending then key UTF-8 byte order, results carry the
// existing window fields and no partition field, there is no error and no
// extra idle result, and the end-1600 windows remain open at end of input.
func TestIdleClosesOverlappingSlidingBatch(t *testing.T) {
	var out, late bytes.Buffer
	if err := runIdleBatch(t, &out, &late, 0); err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if got := out.String(); got != idleBatchWant() {
		t.Fatalf("idle batch mismatch:\n got: %q\nwant: %q", got, idleBatchWant())
	}
