	if !errors.As(err, &oe) {
		t.Fatalf("expected *OutputError, got %T: %v", err, err)
	}
	if oe.Line != 7 {
		t.Errorf("Line = %d, want 7 (the idle declaration that triggered the batch)", oe.Line)
	}
