	if !strings.Contains(err.Error(), wantDetail) {
		t.Errorf("error %q must identify %s", err.Error(), wantDetail)
	}
	if !errors.Is(err, errSentinelOutput) {
		t.Errorf("errors.Is must expose the writer's original error, got %v", err)
	}

	first := `{"key":"a","start":0,"end":1000,"count":1,"sum":2}` + "\n"
	wantKept := first + `{"ke` // 4-byte prefix of the "b" result accepted
	if got := out.got.String(); got != wantKept {
		t.Fatalf("complete result and accepted prefix must be retained verbatim:\n got: %q\nwant: %q", got, wantKept)
	}
}

// Same mid-batch failure, but the writer accepts too few bytes without ever
// returning an error: that is still a fatal output failure the caller can
// recognize as io.ErrShortWrite, with the same retention and stop-processing
// semantics as the error-returning case.
func TestIdleBatchShortWriteWithoutErrorFails(t *testing.T) {
	// accept=40: the "a" line (49 bytes + newline) is short on the very first
	// write, so use accept large enough to fully take "a" but truncate "b".
	firstLen := len(`{"key":"a","start":0,"end":1000,"count":1,"sum":2}`) + 1
	out := &shortWriter{accept: firstLen + 3} // full "a" line, then a 3-byte prefix of "b"
	err := runIdleBatch(t, out, &bytes.Buffer{}, 0)
	var oe *OutputError
	if !errors.As(err, &oe) {
		t.Fatalf("expected *OutputError for nil-error short write, got %T: %v", err, err)
	}
	if !errors.Is(err, io.ErrShortWrite) {
		t.Errorf("short write must be errors.Is io.ErrShortWrite, got %v", err)
	}
	if oe.Line != 7 || oe.Kind != "window result" {
		t.Errorf("got Kind=%q Line=%d, want window result at the line-7 idle declaration", oe.Kind, oe.Line)
	}
	wantDetail := fmt.Sprintf("key %q window [%d,%d)", "b", 0, 1000)
	if !strings.Contains(err.Error(), wantDetail) {
		t.Errorf("error %q must identify %s", err.Error(), wantDetail)
	}

	first := `{"key":"a","start":0,"end":1000,"count":1,"sum":2}` + "\n"
	wantKept := first + `{"k` // 3-byte prefix of the "b" line
	if got := out.got.String(); got != wantKept {
		t.Fatalf("retained bytes mismatch:\n got: %q\nwant: %q", got, wantKept)
	}
	// Exactly two writes attempted: full "a" and the truncated "b"; no third
	// result and no closure from the trailing line-8 watermark.
	if out.calls != 2 {
		t.Errorf("writer called %d times, want exactly 2", out.calls)
	}
}

// Blank physical lines before the idle declaration are skipped but counted:
// the output failure must still point at the physical line of the idle
// declaration, never at its ordinal among valid records.
func TestIdleBatchFailureLineNumbersCountBlankLines(t *testing.T) {
	const blanks = 2 // idle moves from physical line 7 to line 9
	out := &failOnCallWriter{failAt: 1, err: errSentinelOutput}
	err := runIdleBatch(t, out, &bytes.Buffer{}, blanks)
	var oe *OutputError
	if !errors.As(err, &oe) {
		t.Fatalf("expected *OutputError, got %T: %v", err, err)
	}
	wantLine := 7 + blanks
	if oe.Line != wantLine {
		t.Errorf("Line = %d, want %d (physical lines, blanks included)", oe.Line, wantLine)
	}
	if !errors.Is(err, errSentinelOutput) {
		t.Errorf("errors.Is must expose the writer's original error, got %v", err)
	}
}

