package edgefleet

import (
	"bytes"
	"errors"
	"fmt"
	"io"
	"strings"
	"testing"
)

// idleBatchInput is the shared fixture for the "one idle declaration closes
// several overlapping sliding windows at once" guarantees.
//
// Window length 1000ms, starts every 600ms (0, 600, 1200, ...), two
// partitions. Both partitions have fed overlapping windows; partition 0 is
// far ahead while partition 1 stays at watermark 600. Declaring partition 1
// idle drops it from the effective watermark, which immediately jumps to
// partition 0's 1200 and closes one batch of windows:
//
//   - "a" p0 @100  value 2 -> [0,1000)
//   - "k" p0 @700  value 4 + p1 @900 value 6 -> [0,1000) count2 sum10
//   - "b" p0 @700  value 5 -> [600,1600)
//   - "k" p0 @700  value 4 + p1 @900 value 6 -> [600,1600) count2 sum10
//
// At effective watermark 1200 only windows with end <= 1200 close, so the
// ready batch is:
//
//	[0,1000)  "a" end 1000
//	[0,1000)  "k" end 1000
//	[600,1600) "b" is end 1600 -> stays open
//
// plus a window ending exactly at 1200 so different keys share an end time:
//
//   - "b" p0 @200 value 7 -> [0,1000) and one window ending at 1200. With
//     length 1000 and slide 600 no start k*600 has start+1000 == 1200, so a
//     shared-end 1200 window comes from [200,1200) only via slide 600? No
//     such aligned window exists; instead use the genuinely shared end 1000
//     (keys "a" and "k") and a second shared end via key "b":
//
