		`{"type":"event","key":"b","time":700,"value":5,"partition":0}`,  // [0,1000),[600,1600)
		`{"type":"event","key":"k","time":700,"value":4,"partition":0}`,  // [0,1000),[600,1600)
		`{"type":"event","key":"k","time":900,"value":6,"partition":1}`,  // [0,1000),[600,1600)
		`{"type":"watermark","time":1200,"partition":0}`,                 // p0 ahead
		`{"type":"watermark","time":600,"partition":1}`,                  // effective = 600: nothing closes
		`{"type":"idle","partition":1}`,                                  // effective = 1200: closes end<=1200
		`{"type":"watermark","time":1600,"partition":0}`,                 // only reached if failure doesn't stop
	}
